import createAssetResolver from '@ntgovernment/squiz-factory/utils/createAssetResolver';

export default {
    async main({title = 'On this page', advanced: {hn = 'h2', area = '.content-area'}}, info) {
        const {
            ctx: { assetId },
            fns,
            editor,
            env: { dxpApiIdentifier } = {}
        } = info;
        if (!dxpApiIdentifier) {
            return `<span data-anchor-nav>${!editor ? '<!--' : ''}
                <code>dxpApiIdentifier</code> must be set in the DXP Components Set.
            ${!editor ? '-->' : ''}</div>`;
        }
        
        const assetResolver = createAssetResolver(dxpApiIdentifier, info);
        
        const key = 'anchor_nav';
        const result = await assetResolver(assetId);

        return `${
            result?.data?.metadata?.sidebar_items?.includes(key) ?
            `<span data-anchor-nav='${JSON.stringify({ title, hn, area })}'></span>` :
            `<span data-anchor-nav>${!editor ? '<!--' : ''}
                ${key}: disabled ${JSON.stringify(result ?? null)}
             ${!editor ? '-->' : ''}</div>`
        }`;
    }
}
